import React, { useState, useEffect, useRef, useMemo } from 'react';
import { X, FileText, Download } from 'lucide-react';
import { Room } from '../types';
import { calculateBillPeriod } from '../utils';

interface BillPreviewModalProps {
  room: Room;
  onClose: () => void;
}

export const BillPreviewModal: React.FC<BillPreviewModalProps> = ({ room, onClose }) => {
  const [mode, setMode] = useState<'text' | 'image'>('text');
  const [imgSrc, setImgSrc] = useState<string | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Dates
  const [startDate] = useState(() => {
    if (room.billStartDate) return room.billStartDate;
    const { start } = calculateBillPeriod(room.payDay || 1);
    return start;
  });

  const [endDate] = useState(() => {
    if (room.billEndDate) return room.billEndDate;
    if (!room.billStartDate) {
         const { end } = calculateBillPeriod(room.payDay || 1);
         return end;
    }
    const start = new Date(room.billStartDate);
    const end = new Date(start);
    end.setMonth(end.getMonth() + 1);
    return `${end.getFullYear()}-${String(end.getMonth() + 1).padStart(2, '0')}-${String(end.getDate()).padStart(2, '0')}`;
  });

  const getVal = (v: string | number | undefined) => parseFloat(String(v)) || 0;

  const ePrev = getVal(room.elecPrev);
  const eCurr = getVal(room.elecCurr);
  const eUsage = eCurr - ePrev;
  // Fallback to 0 if not set
  const ePrice = getVal(room.fixedElecPrice || 0);
  const eTotal = Math.max(0, eUsage * ePrice);
  const hasElec = eUsage > 0 || room.elecCurr !== '';

  const wPrev = getVal(room.waterPrev);
  const wCurr = getVal(room.waterCurr);
  const wUsage = wCurr - wPrev;
  // Fallback to 0 if not set
  const wPrice = getVal(room.fixedWaterPrice || 0);
  const wTotal = Math.max(0, wUsage * wPrice);
  const hasWater = wUsage > 0 || room.waterCurr !== '';

  const xTotal = (room.extraFees || []).reduce((s, i) => s + getVal(i.amount), 0);
  const total = getVal(room.rent) + eTotal + wTotal + xTotal;
  const depositVal = getVal(room.deposit);

  const dateStr = useMemo(() => {
    if (!startDate || !endDate) return '';
    const formatFull = (s: string) => {
        const [y, m, d] = s.split('-');
        return `${y}年${parseInt(m)}月${parseInt(d)}日`;
    };
    return `${formatFull(startDate)} 至 ${formatFull(endDate)}`;
  }, [startDate, endDate]);

  // Text Content
  const textContent = `【房租收据】\n日期：${dateStr}\n` + 
    `----------------\n` +
    `🏠 房号：${room.roomNo}\n` + 
    (room.tenantName ? `👤 租客：${room.tenantName}\n` : '') + 
    `💰 房租：${room.rent}元\n` + 
    (hasElec ? `⚡ 电费：${eTotal.toFixed(1)}元\n   读数：${ePrev} → ${eCurr}\n   计算：${eUsage.toFixed(1)}度 × ${ePrice}元\n` : '') + 
    (hasWater ? `💧 水费：${wTotal.toFixed(1)}元\n   读数：${wPrev} → ${wCurr}\n   计算：${wUsage.toFixed(1)}吨 × ${wPrice}元\n` : '') + 
    (room.extraFees || []).map(f => getVal(f.amount) > 0 ? `🧾 ${f.name}：${f.amount}元\n` : '').join('') + 
    `----------------\n` + 
    `💵 总计：${total.toFixed(1)} 元\n` +
    (depositVal > 0 ? `(已收押金：${depositVal}元)\n` : '');

  useEffect(() => {
    if (mode === 'image' && canvasRef.current && dateStr) {
      const ctx = canvasRef.current.getContext('2d');
      if (!ctx) return;

      // --- 1. Layout Calculation ---
      const PADDING_TOP = 160;
      const LINE_HEIGHT = 60; // Standard row height
      const READING_HEIGHT = 40; // Height for reading/calc sub-rows
      const TOTAL_BLOCK_HEIGHT = 120;
      const FOOTER_HEIGHT = 60;

      let h = PADDING_TOP;

      h += LINE_HEIGHT; // Room No
      if (room.tenantName) h += LINE_HEIGHT; // Tenant
      h += LINE_HEIGHT; // Rent (Separate Line)

      if (hasElec) {
        h += LINE_HEIGHT; // Elec Money
        h += READING_HEIGHT * 2; // Reading + Calc
        h += 10; // Extra padding
      }

      if (hasWater) {
        h += LINE_HEIGHT; // Water Money
        h += READING_HEIGHT * 2; // Reading + Calc
        h += 10;
      }

      if (room.extraFees) h += (room.extraFees.length * LINE_HEIGHT);

      h += TOTAL_BLOCK_HEIGHT;
      if (depositVal > 0) h += 40;
      h += FOOTER_HEIGHT;

      const width = 600;
      const height = h;

      canvasRef.current.width = width;
      canvasRef.current.height = height;

      // --- 2. Drawing ---

      // Background
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, width, height);

      // Header
      ctx.fillStyle = '#2563EB';
      ctx.fillRect(0, 0, width, 16);

      ctx.fillStyle = '#111827';
      ctx.font = 'bold 36px "PingFang SC", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('房 屋 租 金 收 据', width / 2, 80);

      ctx.font = '22px "PingFang SC", sans-serif';
      ctx.fillStyle = '#6B7280';
      ctx.fillText(dateStr, width / 2, 120);

      ctx.beginPath();
      ctx.moveTo(40, 140);
      ctx.lineTo(width - 40, 140);
      ctx.strokeStyle = '#E5E7EB';
      ctx.lineWidth = 2;
      ctx.stroke();

      let y = 200; // Start Y
      ctx.textAlign = 'left';

      // Standard Row Function
      const drawLine = (icon: string, label: string, value: string, isBoldValue = true) => {
        ctx.font = '26px "PingFang SC", sans-serif';
        ctx.fillStyle = '#374151'; // Dark Gray
        ctx.fillText(`${icon} ${label}`, 40, y);

        if (value) {
            ctx.textAlign = 'right';
            ctx.font = isBoldValue ? 'bold 28px "PingFang SC", sans-serif' : '26px "PingFang SC", sans-serif';
            ctx.fillStyle = '#111827'; // Black
            ctx.fillText(value, width - 40, y);
            ctx.textAlign = 'left';
        }
        y += LINE_HEIGHT;
      };

      // --- Content Drawing ---

      // 1. Room
      drawLine('🏠', `房号：${room.roomNo}`, '');

      // 2. Tenant (Own Line, No duplicate on right)
      if (room.tenantName) {
        drawLine('👤', `租客：${room.tenantName}`, '');
      }

      // 3. Rent (Own Line)
      drawLine('💰', '房租', `¥${room.rent}`);

      // 4. Elec
      if (hasElec) {
        drawLine('⚡', '电费', `¥${eTotal.toFixed(1)}`);

        // Manual detail drawing for better spacing
        y -= 25; // Tuck up under the main line slightly
        ctx.font = '20px "PingFang SC", sans-serif';
        ctx.fillStyle = '#9CA3AF';

        ctx.fillText(`读数：${ePrev} → ${eCurr}`, 75, y);
        y += 32; // Gap between Reading and Calculation

        ctx.fillText(`计算：${eUsage.toFixed(1)}度 × ${ePrice}元`, 75, y);
        y += 35; // Gap before next section
      }

      // 5. Water
      if (hasWater) {
        drawLine('💧', '水费', `¥${wTotal.toFixed(1)}`);

        y -= 25; 
        ctx.font = '20px "PingFang SC", sans-serif';
        ctx.fillStyle = '#9CA3AF';

        ctx.fillText(`读数：${wPrev} → ${wCurr}`, 75, y);
        y += 32;

        ctx.fillText(`计算：${wUsage.toFixed(1)}吨 × ${wPrice}元`, 75, y);
        y += 35;
      }

      // 6. Extras
      if (room.extraFees) {
        room.extraFees.forEach(f => {
          if (getVal(f.amount) > 0 || f.name) {
             drawLine('🧾', f.name || '杂费', `¥${f.amount}`);
          }
        });
      }

      // Total Box
      y += 10;
      ctx.fillStyle = '#FEF2F2';
      ctx.fillRect(30, y, width - 60, 90);

      y += 55;
      ctx.fillStyle = '#DC2626';
      ctx.font = 'bold 32px "PingFang SC", sans-serif';
      ctx.fillText('总计应收', 60, y);

      ctx.textAlign = 'right';
      ctx.font = 'bold 40px "PingFang SC", sans-serif';
      ctx.fillText(`¥${total.toFixed(1)}`, width - 60, y);

      y += 60;

      if (depositVal > 0) {
        y += 10;
        ctx.font = '22px "PingFang SC", sans-serif';
        ctx.fillStyle = '#6B7280';
        ctx.textAlign = 'right';
        ctx.fillText(`(已收押金: ¥${depositVal})`, width - 40, y);
        y += 40;
      }

      // Footer
      y += 30;
      ctx.textAlign = 'center';
      ctx.font = '18px "PingFang SC", sans-serif';
      ctx.fillStyle = '#9CA3AF';
      ctx.fillText('感谢您的配合，请及时转账', width / 2, y);

      setImgSrc(canvasRef.current.toDataURL("image/png"));
    }
  }, [mode, room, dateStr, eTotal, eUsage, total, wTotal, wUsage, ePrev, eCurr, wPrev, wCurr, depositVal, hasElec, hasWater, ePrice, wPrice]);

  const downloadImage = () => {
    if (imgSrc) {
        const link = document.createElement('a');
        link.download = `收据_${room.roomNo}_${dateStr}.png`;
        link.href = imgSrc;
        link.click();
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 z-[100]">
      <div className="bg-white w-full max-w-md rounded-2xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-xl flex items-center gap-2">
            <FileText className="text-blue-600"/> 账单预览
          </h3>
          <button onClick={onClose}><X size={20} className="text-gray-400"/></button>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-lg mb-4 flex-shrink-0">
          <button onClick={() => setMode('text')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${mode === 'text' ? 'bg-white shadow text-black' : 'text-gray-500'}`}>
            📝 纯文本
          </button>
          <button onClick={() => setMode('image')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${mode === 'image' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>
            🖼️ 正式图片
          </button>
        </div>

        <div className="flex-1 overflow-y-auto bg-gray-50 rounded-xl border border-gray-200 p-4 mb-4 flex justify-center">
          {mode === 'text' ? (
            <textarea 
              className="w-full h-64 bg-transparent resize-none outline-none text-sm font-mono text-gray-700 whitespace-pre-wrap" 
              value={textContent} 
              readOnly
            />
          ) : (
            <div className="w-full flex flex-col items-center">
              <canvas ref={canvasRef} className="hidden" />
              {imgSrc ? (
                  <img src={imgSrc} alt="Bill" className="w-full h-auto rounded shadow-lg border border-gray-100" />
              ) : (
                  <div className="text-gray-400">正在生成...</div>
              )}
              <p className="text-xs text-gray-400 mt-2">长按图片可保存，或点击下方按钮</p>
            </div>
          )}
        </div>

        {mode === 'text' ? (
            <button 
              onClick={() => navigator.clipboard.writeText(textContent).then(() => alert("文本已复制"))} 
              className="w-full py-3 rounded-xl font-bold text-white shadow-md transition-colors bg-black"
            >
              复制文本
            </button>
        ) : (
            <button 
              onClick={downloadImage} 
              className="w-full py-3 rounded-xl font-bold text-white shadow-md transition-colors bg-blue-600 flex items-center justify-center gap-2"
            >
              <Download size={18} /> 保存到相册
            </button>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ArrowLeft, X, Trash2 } from 'lucide-react';
import { AppConfig, Room } from '../types';

interface AddRoomModalProps {
  config: AppConfig;
  onSave: (data: Partial<Room>) => void;
  onBatchConfirmed: (previewRooms: Partial<Room>[]) => void;
  onCancel: () => void;
  confirmAction: (title: string, content: string, action: () => void) => void;
}

export const AddRoomModal: React.FC<AddRoomModalProps> = ({ 
  config, 
  onSave, 
  onBatchConfirmed, 
  onCancel, 
  confirmAction 
}) => {
  const [mode, setMode] = useState<'single' | 'batch'>('single');
  const [step, setStep] = useState(1);
  const [data, setData] = useState({
    roomNo: '',
    rent: '', 
    moveInDate: '', // Full date string
    payDay: '',     // Derived day of month
    deposit: '',
    prefix: '',
    floorStart: '1',
    floorEnd: '6',
    roomCount: '4',
    fixedElecPrice: '',
    fixedWaterPrice: ''
  });
  const [previewRooms, setPreviewRooms] = useState<Partial<Room>[]>([]);

  const handleChange = (f: string, v: string) => {
    let updates: any = { [f]: v };
    // Automatically set payDay if moveInDate changes
    if (f === 'moveInDate' && v) {
      const day = new Date(v).getDate();
      if (!isNaN(day)) updates.payDay = day.toString();
    }
    setData(prev => ({ ...prev, ...updates }));
  };

  const handleGeneratePreview = () => {
    const start = parseInt(data.floorStart), end = parseInt(data.floorEnd), rCount = parseInt(data.roomCount);
    if (isNaN(start) || isNaN(end) || isNaN(rCount)) return alert("请填写正确的数字");

    const tempRooms: Partial<Room>[] = [];
    for (let f = start; f <= end; f++) {
      for (let r = 1; r <= rCount; r++) {
        const roomNo = `${data.prefix}${f}${r.toString().padStart(2, '0')}`;
        tempRooms.push({
          roomNo,
          rent: data.rent || config.defaultRent, 
          payDay: data.payDay ? parseInt(data.payDay) : 1, 
          moveInDate: data.moveInDate,
          deposit: data.deposit,
          fixedElecPrice: data.fixedElecPrice,
          fixedWaterPrice: data.fixedWaterPrice
        });
      }
    }
    setPreviewRooms(tempRooms);
    setStep(2);
  };

  const updatePreviewItem = (index: number, field: keyof Room, value: string) => {
    setPreviewRooms(prev => {
      const newArr = [...prev];
      // @ts-ignore
      newArr[index][field] = value;
      // Also sync payDay if moving date changes in preview
      if (field === 'moveInDate' && value) {
         const day = new Date(value).getDate();
         if (!isNaN(day)) newArr[index].payDay = day;
      }
      return newArr;
    });
  };

  const requestRemoveItem = (index: number) => {
    confirmAction(
      "确认移除?",
      `确定不生成房间 ${previewRooms[index].roomNo} 吗？`,
      () => setPreviewRooms(prev => prev.filter((_, i) => i !== index))
    );
  };

  const handleSingleSave = () => {
      onSave({ 
          ...data, 
          rent: data.rent || config.defaultRent,
          payDay: data.payDay ? parseInt(data.payDay) : 1
      });
  };

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4 z-50 animate-in fade-in">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh]">

        <div className="flex justify-between items-center mb-4 flex-shrink-0">
          <h2 className="text-xl font-bold text-gray-900">{step === 1 ? '添加资产' : '生成预览'}</h2>
          <button onClick={onCancel}><X size={24} className="text-gray-400"/></button>
        </div>

        {step === 1 && (
          <>
            <div className="flex bg-gray-100 p-1 rounded-lg mb-4 flex-shrink-0">
              <button onClick={() => setMode('single')} className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${mode === 'single' ? 'bg-white text-black shadow-sm' : 'text-gray-500'}`}>单个添加</button>
              <button onClick={() => setMode('batch')} className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${mode === 'batch' ? 'bg-white text-black shadow-sm' : 'text-gray-500'}`}>批量生成</button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 min-h-0 px-1">
              {mode === 'single' ? (
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase">房间号</label>
                  <input className="w-full text-xl font-bold border-b-2 py-2 outline-none" placeholder="301" value={data.roomNo} onChange={e => handleChange('roomNo', e.target.value)} />
                </div>
              ) : (
                <>
                  <div>
                    <label className="text-xs font-bold text-gray-400 uppercase">前缀 (如: A栋-)</label>
                    <input className="w-full text-lg font-bold border-b-2 py-2 outline-none" placeholder="A栋-" value={data.prefix} onChange={e => handleChange('prefix', e.target.value)} />
                  </div>
                  <div className="flex gap-4 items-center">
                    <div>
                      <label className="text-xs font-bold text-gray-400 uppercase">起始层</label>
                      <input type="number" className="w-full text-lg font-bold border-b-2 py-2 outline-none" value={data.floorStart} onChange={e => handleChange('floorStart', e.target.value)} />
                    </div>
                    <span className="text-gray-300 font-bold pt-4">至</span>
                    <div>
                      <label className="text-xs font-bold text-gray-400 uppercase">结束层</label>
                      <input type="number" className="w-full text-lg font-bold border-b-2 py-2 outline-none" value={data.floorEnd} onChange={e => handleChange('floorEnd', e.target.value)} />
                    </div>
                  </div>
                  <div>
                    <label className="text-xs font-bold text-gray-400 uppercase">每层几户</label>
                    <input type="number" className="w-full text-lg font-bold border-b-2 py-2 outline-none" value={data.roomCount} onChange={e => handleChange('roomCount', e.target.value)} />
                  </div>
                </>
              )}

              <div className="grid grid-cols-2 gap-4 pt-2">
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase">租金(元)</label>
                  <input type="number" className="w-full font-bold border-b py-1 outline-none" placeholder={config.defaultRent} value={data.rent} onChange={e => handleChange('rent', e.target.value)} />
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase">押金(元)</label>
                  <input type="number" className="w-full font-bold border-b py-1 outline-none" placeholder="0" value={data.deposit} onChange={e => handleChange('deposit', e.target.value)} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase">入住日期</label>
                  <input 
                    type="date" 
                    className="w-full font-bold border-b py-1 outline-none" 
                    value={data.moveInDate} 
                    onChange={e => handleChange('moveInDate', e.target.value)} 
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase">收租时间(号)</label>
                  <input 
                    type="number" 
                    className="w-full font-bold border-b py-1 outline-none" 
                    placeholder="1"
                    value={data.payDay} 
                    onChange={e => handleChange('payDay', e.target.value)} 
                  />
                </div>
              </div>

              <div className="bg-gray-50 p-3 rounded-lg mt-2 border border-gray-100">
                <p className="text-xs font-bold text-gray-500 mb-2">💰 独立水电 (选填)</p>
                <div className="flex gap-3">
                  <input placeholder="电费单价" className="w-full bg-white border rounded px-2 py-1.5 text-sm" value={data.fixedElecPrice} onChange={e => handleChange('fixedElecPrice', e.target.value)} />
                  <input placeholder="水费单价" className="w-full bg-white border rounded px-2 py-1.5 text-sm" value={data.fixedWaterPrice} onChange={e => handleChange('fixedWaterPrice', e.target.value)} />
                </div>
              </div>
            </div>

            <button 
              onClick={() => mode === 'single' ? handleSingleSave() : handleGeneratePreview()} 
              className="w-full mt-4 py-3 bg-black text-white rounded-lg font-bold shadow-lg flex-shrink-0"
            >
              {mode === 'single' ? '确认添加' : '下一步：预览并微调'}
            </button>
          </>
        )}

        {step === 2 && (
          <>
            <div className="flex items-center justify-between mb-2 flex-shrink-0">
              <button onClick={() => setStep(1)} className="text-sm text-gray-500 font-bold flex items-center gap-1 bg-gray-100 px-3 py-1 rounded-full">
                <ArrowLeft size={14}/> 返回修改
              </button>
              <span className="text-xs text-gray-400">共 {previewRooms.length} 间</span>
            </div>

            <div className="flex-1 overflow-y-auto space-y-3 min-h-0 pr-1 pb-2">
              {previewRooms.map((room, idx) => (
                <div key={idx} className="p-3 bg-white border border-gray-200 rounded-xl shadow-sm space-y-2 relative group">
                  <div className="flex justify-between items-center border-b border-gray-50 pb-2">
                    <span className="font-bold text-gray-800 text-lg">{room.roomNo}</span>
                    <button onClick={() => requestRemoveItem(idx)} className="bg-red-50 text-red-500 p-1.5 rounded-lg text-xs font-bold flex items-center gap-1">
                      <Trash2 size={12}/> 删除
                    </button>
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    <div className="flex-1">
                      <label className="text-[10px] text-gray-400 block">租金</label>
                      <input type="number" className="w-full bg-gray-50 border rounded px-2 py-1 text-sm font-bold text-gray-800 outline-none" value={room.rent} onChange={e => updatePreviewItem(idx, 'rent', e.target.value)} />
                    </div>
                    <div className="flex-1">
                      <label className="text-[10px] text-gray-400 block">押金</label>
                      <input type="number" className="w-full bg-gray-50 border rounded px-2 py-1 text-sm font-bold text-gray-800 outline-none" value={room.deposit} onChange={e => updatePreviewItem(idx, 'deposit', e.target.value)} />
                    </div>
                    <div className="flex-1">
                      <label className="text-[10px] text-gray-400 block">入住日期</label>
                      <input type="date" className="w-full bg-gray-50 border rounded px-2 py-1 text-xs font-bold text-gray-800 outline-none" value={room.moveInDate || ''} onChange={e => updatePreviewItem(idx, 'moveInDate', e.target.value)} />
                    </div>
                    <div className="flex-1">
                      <label className="text-[10px] text-gray-400 block">收租日</label>
                      <input type="number" className="w-full bg-gray-50 border rounded px-2 py-1 text-sm font-bold text-gray-800 outline-none" value={room.payDay} onChange={e => updatePreviewItem(idx, 'payDay', e.target.value)} />
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <button onClick={() => onBatchConfirmed(previewRooms)} className="w-full mt-4 py-3 bg-blue-600 text-white rounded-lg font-bold shadow-lg flex-shrink-0">
              确认生成全部
            </button>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { X, Copy, Calendar, ArrowRight } from 'lucide-react';
import { Room } from '../types';

interface BatchBillModalProps {
  rooms: Room[];
  onClose: () => void;
}

export const BatchBillModal: React.FC<BatchBillModalProps> = ({ rooms, onClose }) => {
  // Dates default to empty so user can select without deleting
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const getVal = (v: string | number | undefined) => parseFloat(String(v)) || 0;

  const dateStr = useMemo(() => {
    if (!startDate || !endDate) return '';

    const formatFull = (s: string) => {
        const [y, m, d] = s.split('-');
        return `${y}年${parseInt(m)}月${parseInt(d)}日`;
    };

    return `${formatFull(startDate)} 至 ${formatFull(endDate)}`;
  }, [startDate, endDate]);

  const textContent = useMemo(() => {
    return rooms.map(room => {
        const ePrev = getVal(room.elecPrev);
        const eCurr = getVal(room.elecCurr);
        const eUsage = eCurr - ePrev;
        // Fallback to 0 if not set
        const ePrice = getVal(room.fixedElecPrice || 0);
        const eTotal = Math.max(0, eUsage * ePrice);

        const wPrev = getVal(room.waterPrev);
        const wCurr = getVal(room.waterCurr);
        const wUsage = wCurr - wPrev;
        // Fallback to 0 if not set
        const wPrice = getVal(room.fixedWaterPrice || 0);
        const wTotal = Math.max(0, wUsage * wPrice);

        const xTotal = (room.extraFees || []).reduce((s, i) => s + getVal(i.amount), 0);
        const total = getVal(room.rent) + eTotal + wTotal + xTotal;
        const depositVal = getVal(room.deposit);

        return `【${room.roomNo} 房租】${dateStr}\n` + 
        `🏠 房租：${room.rent}元\n` + 
        (eUsage > 0 || room.elecCurr ? `⚡ 电费：${ePrev}→${eCurr} (${eUsage.toFixed(1)}度) = ${eTotal.toFixed(1)}元\n` : '') + 
        (wUsage > 0 || room.waterCurr ? `💧 水费：${wPrev}→${wCurr} (${wUsage.toFixed(1)}吨) = ${wTotal.toFixed(1)}元\n` : '') + 
        (room.extraFees || []).map(f => getVal(f.amount) > 0 ? `🧾 ${f.name}：${f.amount}元\n` : '').join('') + 
        `💰 总计：${total.toFixed(1)} 元\n` + 
        (depositVal > 0 ? `(已收押金：${depositVal}元)\n` : '') + 
        `----------------\n`;
    }).join('\n');
  }, [rooms, dateStr]);

  const copyAll = () => {
    navigator.clipboard.writeText(textContent).then(() => alert("全部账单已复制"));
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
