import React from 'react';
import { 
  X, CheckSquare, Search, BookOpen, History, 
  Building2, RotateCcw, FileText, Square, CheckCircle, Plus,
  ListChecks, Copy, Download, Cloud, AlertCircle, Check, Settings2
} from 'lucide-react';
import { Room, AppConfig, ActionHandlers, ModalState, InstallPromptEvent } from '../types';
import { getBuildingName } from '../utils';

interface RoomListViewProps {
  rooms: Room[];
  search: {
    input: string;
    setInput: (v: string) => void;
    active: string;
    run: () => void;
    clear: () => void;
  };
  filter: {
    building: string;
    setBuilding: (v: string) => void;
    date: string;
    setDate: (v: string) => void;
  };
  batch: {
    isMode: boolean;
    setMode: (v: boolean) => void;
    ids: Set<string>;
    setIds: (v: Set<string>) => void;
  };
  actions: ActionHandlers;
  openGuide: () => void;
  navigate: (view: 'list' | 'edit' | 'add', id?: string) => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
  config: AppConfig;
  installPrompt: InstallPromptEvent | null;
  onInstall: () => void;
  cloudUser: any;
}

export const RoomListView: React.FC<RoomListViewProps> = ({ 
  rooms, search, filter, batch, actions, navigate, 
  setModal, openGuide, confirmAction, config,
  installPrompt, onInstall, cloudUser
}) => {
  const getVal = (v: any) => parseFloat(v) || 0;

  const calcDetails = (r: Room) => {
    const ep = r.fixedElecPrice || '0';
    const wp = r.fixedWaterPrice || '0';
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    const rent = getVal(r.rent);
    return {
        rent,
        elec: Math.max(0, e),
        water: Math.max(0, w),
        total: Math.max(0, rent + Math.max(0, e) + Math.max(0, w) + extra)
    };
  };

  const allBuildings = ['all', ...new Set(rooms.map(r => getBuildingName(r.roomNo)))].sort();

  let filtered = rooms;
  if (search.active) filtered = filtered.filter(r => r.roomNo.toLowerCase().includes(search.active.toLowerCase()));
  if (filter.building !== 'all') filtered = filtered.filter(r => getBuildingName(r.roomNo) === filter.building);
  if (filter.date !== 'all') filtered = filtered.filter(r => (r.payDay || 1) === parseInt(filter.date));

  const allPayDays = [...new Set(rooms.map(r => r.payDay || 1))].sort((a, b) => Number(a) - Number(b));

  // Grouping Logic
  interface RoomGroup {
    label?: string;
    rooms: Room[];
  }

  const sortRooms = (list: Room[]) => list.sort((a, b) => { 
      if (a.status !== b.status) return a.status === 'unpaid' ? -1 : 1; 
      return a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }); 
  });

  let displayGroups: RoomGroup[] = [];
  if (filter.date === 'all') {
      displayGroups = [{ rooms: sortRooms([...filtered]) }];
  } else {
      if (filtered.length > 0) {
        displayGroups = [{
            label: `${filter.date}号收租 (共${filtered.length}户)`,
            rooms: sortRooms([...filtered])
        }];
      }
  }

  // Statistics Calculation
  const stats = filtered.reduce((acc, r) => {
      const d = calcDetails(r);
      acc.total += d.total;
      acc.rent += d.rent;
      acc.elec += d.elec;
      acc.water += d.water;
      if (r.status === 'paid') acc.collected += d.total;
      return acc;
  }, { total: 0, rent: 0, elec: 0, water: 0, collected: 0 });

  const toggleSelect = (id: string) => { 
    const newSet = new Set(batch.ids); 
    if (newSet.has(id)) newSet.delete(id); else newSet.add(id); 
    batch.setIds(newSet); 
  };

  const handleSelectAll = () => {
      const allFilteredIds = filtered.map(r => r.id);
      const isAllSelected = allFilteredIds.every(id => batch.ids.has(id));
      if (isAllSelected) {
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.delete(id));
          batch.setIds(newSet);
      } else {
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.add(id));
          batch.setIds(newSet);
      }
  };

  const openBatchBill = () => {
      setModal({ type: 'batchBill', data: Array.from(batch.ids) });
  };

  return (
    <div className="pb-24">
      <div className="sticky top-0 z-30 bg-[#F5F7FA]/95 backdrop-blur-sm border-b border-gray-200 shadow-sm">

        {/* Auth Status Banner - Compressed */}
        <div 
          onClick={() => setModal({ type: 'cloudAuth' })}
          className={`px-4 py-1 flex items-center justify-center gap-2 text-xs font-bold cursor-pointer transition-colors ${cloudUser ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-600 animate-pulse'}`}
        >
          {cloudUser ? (
            <><Check size={10}/> 已登录: {cloudUser.email}</>
          ) : (
            <><AlertCircle size={10}/> 未登录 (数据不保存) - 点击登录</>
          )}
        </div>

        <div className="px-4 py-2">
          {batch.isMode ? (
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 w-full bg-blue-50 p-2 rounded-lg border border-blue-200">
                    <button onClick={() => { batch.setMode(false); batch.setIds(new Set()); }} className="p-1 rounded hover:bg-blue-100">
                        <X className="text-blue-500" size={20}/>
                    </button>
                    <span className="font-bold text-blue-800 text-sm">已选 {batch.ids.size}</span>

                    <div className="ml-auto flex gap-2">
                        <button onClick={handleSelectAll} className="text-xs px-2 py-1.5 bg-white text-blue-600 rounded border border-blue-200 font-bold flex items-center gap-1">
                            <ListChecks size={14}/> 全选
                        </button>
                    </div>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={() => setModal({ type: 'batchEdit' })} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-gray-700 rounded border font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Settings2 size={14}/> 批量设置
                    </button>
                    <button 
                        onClick={openBatchBill} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-blue-600 rounded border border-blue-200 font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Copy size={14}/> 批量账单
                    </button>
                    <button 
                        onClick={() => confirmAction("批量删除?", `确定删除选中的 ${batch.ids.size} 个房间吗？`, actions.deleteBatch)} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-red-600 rounded border border-red-100 font-bold disabled:opacity-50"
                    >
                        删除
                    </button>
                </div>
            </div>
          ) : (
            <div className="flex items-center justify-between w-full">
              <div className="flex-shrink-0">
                <h1 className="text-xl font-black text-gray-800">房租管家</h1>
              </div>

              <div className="flex-1 flex justify-end pl-2">
                 <div className="flex items-center gap-2">
                    {installPrompt && (
                       <button onClick={onInstall} className="flex items-center justify-center gap-1 bg-black text-white px-2 py-1.5 rounded-full text-xs font-bold shadow-md hover:scale-105 transition-transform whitespace-nowrap">
                         <Download size={12}/> <span>安装</span>
                       </button>
                    )}
                    <button onClick={() => setModal({ type: 'cloudAuth' })} className="flex items-center justify-center gap-1 bg-white border border-blue-100 text-blue-600 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-blue-50 shadow-sm whitespace-nowrap">
                      <Cloud size={12}/> <span>云同步</span>
                    </button>
                    <button onClick={openGuide} className="flex items-center justify-center gap-1 bg-blue-100 text-blue-700 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-blue-200 whitespace-nowrap">
                      <BookOpen size={12}/> <span>指南</span>
                    </button>
                    <button onClick={() => setModal({ type: 'history' })} className="flex items-center justify-center gap-1 bg-gray-100 text-gray-700 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 whitespace-nowrap">
                      <History size={12}/> <span>历史</span>
                    </button>
                 </div>
              </div>
            </div>
          )}
        </div>

        {/* Compressed Filters */}
        <div className="bg-white/50 backdrop-blur-sm">
          <div className="px-4 py-1 flex gap-2 overflow-x-auto no-scrollbar">
            {allBuildings.map(b => (
              <button 
                key={b} 
                onClick={() => filter.setBuilding(b)} 
                className={`whitespace-nowrap px-3 py-1 rounded-lg text-xs font-bold transition-all border ${filter.building === b ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-500 border-gray-200'}`}
              >
                <Building2 size={12}/> {b === 'all' ? '所有房产' : b}
              </button>
            ))}
          </div>
          <div className="px-4 py-1 flex gap-2 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => filter.setDate('all')} 
              className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === 'all' ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
            >
              全部日期
            </button>
            {allPayDays.map(day => (
              <button 
                key={day} 
                onClick={() => filter.setDate(day.toString())} 
                className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === day.toString() ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
              >
                {day}号收租
              </button>
            ))}
          </div>
        </div>

        <div className="px-4 py-1.5 flex flex-col gap-1.5 bg-white border-t border-gray-100">
            <div className="flex gap-2">
              <div className="flex-1 flex items-center bg-gray-100 rounded-lg px-2 py-1">
                <Search className="text-gray-400" size={14} />
                <input 
                  className="bg-transparent text-xs p-1.5 outline-none w-full" 
                  placeholder="输入房号..." 
                  value={search.input} 
                  onChange={e => search.setInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && search.run()}
                />
                {search.input && <button onClick={search.clear}><X size={14} className="text-gray-400"/></button>}
              </div>
              <button onClick={search.run} className="bg-blue-600 text-white px-3 py-1 rounded-lg text-xs font-bold flex-shrink-0">搜索</button>
            </div>

            {!batch.isMode && (
                <div className="pt-1.5 border-t border-gray-50">
                    <div className="flex justify-between items-center mb-0.5">
                        <span className="text-xs text-gray-500">应收总计: <b className="text-gray-900 text-sm">¥{stats.total.toLocaleString()}</b></span>
                        <span className="text-xs text-green-600 font-bold">已收: ¥{stats.collected.toLocaleString()}</span>
                    </div>

                    <div className="flex justify-between items-center">
                         <div className="flex gap-2 text-[10px] text-gray-400">
                             <span>房租: ¥{stats.rent.toLocaleString()}</span>
                             <span className="w-px h-3 bg-gray-200"></span>
                             <span>水费: ¥{stats.water.toLocaleString()}</span>
                             <span className="w-px h-3 bg-gray-200"></span>
                             <span>电费: ¥{stats.elec.toLocaleString()}</span>
                         </div>
                         <div className="flex gap-2">
                            <button onClick={() => batch.setMode(true)} className="text-xs font-bold text-gray-600 bg-gray-100 px-2 py-1 rounded-lg flex items-center gap-1 active:bg-gray-200">
                                <CheckSquare size={10}/> 批量
                            </button>
                            <button onClick={() => setModal({ type: 'newMonth' })} className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg flex items-center gap-1 active:bg-blue-100">
                                <RotateCcw size={10}/> 结算
                            </button>
                         </div>
                    </div>
                </div>
            )}
        </div>
      </div>

      <div className="px-4 py-3 space-y-4">
        {displayGroups.map((group, index) => (
          <div key={index}>
            {group.label && (
              <div className="flex items-center gap-2 mb-2 pl-1">
                <span className="bg-gray-200 text-gray-600 text-[10px] font-bold px-2 py-0.5 rounded">{group.label}</span>
                <div className="h-px bg-gray-200 flex-1"></div>
              </div>
            )}
            <div className="grid grid-cols-1 gap-2.5">
              {group.rooms.map(room => {
                const details = calcDetails(room);
                const isPaid = room.status === 'paid';
                const isSelected = batch.ids.has(room.id);
                return (
                  <div 
                    key={room.id} 
                    onClick={() => batch.isMode ? toggleSelect(room.id) : navigate('edit', room.id)} 
                    className={`relative flex items-center gap-4 p-3 rounded-xl border transition-all bg-white ${batch.isMode && isSelected ? 'border-blue-500 bg-blue-50/20' : 'border-gray-100 shadow-[0_2px_5px_rgba(0,0,0,0.02)]'} ${!batch.isMode && isPaid ? 'opacity-60 grayscale' : 'hover:border-blue-200'}`}
                  >
                    {batch.isMode && (
                      <div className={`mr-1 ${isSelected ? 'text-blue-600' : 'text-gray-300'}`}>
                        {isSelected ? <CheckSquare size={20}/> : <Square size={20}/>}
                      </div>
                    )}
                    {!batch.isMode && <div className={`absolute left-0 top-3 bottom-3 w-1 rounded-r-full ${isPaid ? 'bg-green-400' : 'bg-red-500'}`}></div>}
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center mb-1">
                        <div className="flex items-baseline gap-2 overflow-hidden">
                          <span className="text-lg font-bold text-gray-800 whitespace-nowrap">{room.roomNo}</span>
                          {room.tenantName && (
                            <span className="text-base font-bold text-gray-500 truncate">
                              {room.tenantName}
                            </span>
                          )}
                        </div>
                        <span className="text-lg font-bold font-mono text-gray-900 flex-shrink-0 ml-2">¥{details.total.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center h-5">
                        <span className="text-[10px] text-gray-400 flex items-center gap-1">
                          <Building2 size={10}/> {getBuildingName(room.roomNo)}
                          {room.moveInDate && <span className="ml-1 text-gray-400">| 入住: {room.moveInDate}</span>}
                        </span>
                        {!batch.isMode && !isPaid && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); setModal({ type: 'bill', data: room }); }} 
                            className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded hover:bg-blue-100"
                          >
                            账单
                          </button>
                        )}
                        {isPaid && <span className="text-[10px] font-bold text-green-600 flex items-center gap-1"><CheckCircle size={10}/> 已收</span>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {filtered.length === 0 && (
          <div className="text-center text-gray-400 py-20 flex flex-col items-center">
            <FileText size={48} className="mx-auto text-gray-200 mb-2"/>
            <p className="font-bold text-gray-500 mb-2">没有数据</p>
            {!cloudUser && <p className="text-xs text-red-400">请先登录云同步账号</p>}
          </div>
        )}
      </div>

      {!batch.isMode && (
        <button 
          onClick={() => navigate('add')} 
          className="fixed bottom-8 right-6 bg-blue-600 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center z-40 hover:scale-105 transition"
        >
          <Plus size={28} />
        </button>
      )}
    </div>
  );
};

import React from 'react';
import { 
  X, CheckSquare, Search, BookOpen, History, 
  Building2, RotateCcw, FileText, Square, CheckCircle, Plus,
  ListChecks, Copy, Download, Cloud, AlertCircle, Check, Settings2
} from 'lucide-react';
import { Room, AppConfig, ActionHandlers, ModalState, InstallPromptEvent } from '../types';
import { getBuildingName } from '../utils';

interface RoomListViewProps {
  rooms: Room[];
  search: {
    input: string;
    setInput: (v: string) => void;
    active: string;
    run: () => void;
    clear: () => void;
  };
  filter: {
    building: string;
    setBuilding: (v: string) => void;
    date: string;
    setDate: (v: string) => void;
  };
  batch: {
    isMode: boolean;
    setMode: (v: boolean) => void;
    ids: Set<string>;
    setIds: (v: Set<string>) => void;
  };
  actions: ActionHandlers;
  openGuide: () => void;
  navigate: (view: 'list' | 'edit' | 'add', id?: string) => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
  config: AppConfig;
  installPrompt: InstallPromptEvent | null;
  onInstall: () => void;
  cloudUser: any;
}

export const RoomListView: React.FC<RoomListViewProps> = ({ 
  rooms, search, filter, batch, actions, navigate, 
  setModal, openGuide, confirmAction, config,
  installPrompt, onInstall, cloudUser
}) => {
  const getVal = (v: any) => parseFloat(v) || 0;

  const calcDetails = (r: Room) => {
    const ep = r.fixedElecPrice || '0';
    const wp = r.fixedWaterPrice || '0';
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    const rent = getVal(r.rent);
    return {
        rent,
        elec: Math.max(0, e),
        water: Math.max(0, w),
        total: Math.max(0, rent + Math.max(0, e) + Math.max(0, w) + extra)
    };
  };

  const allBuildings = ['all', ...new Set(rooms.map(r => getBuildingName(r.roomNo)))].sort();

  let filtered = rooms;
  if (search.active) filtered = filtered.filter(r => r.roomNo.toLowerCase().includes(search.active.toLowerCase()));
  if (filter.building !== 'all') filtered = filtered.filter(r => getBuildingName(r.roomNo) === filter.building);
  if (filter.date !== 'all') filtered = filtered.filter(r => (r.payDay || 1) === parseInt(filter.date));

  const allPayDays = [...new Set(rooms.map(r => r.payDay || 1))].sort((a, b) => Number(a) - Number(b));

  // Grouping Logic
  interface RoomGroup {
    label?: string;
    rooms: Room[];
  }

  const sortRooms = (list: Room[]) => list.sort((a, b) => { 
      if (a.status !== b.status) return a.status === 'unpaid' ? -1 : 1; 
      return a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }); 
  });

  let displayGroups: RoomGroup[] = [];
  if (filter.date === 'all') {
      displayGroups = [{ rooms: sortRooms([...filtered]) }];
  } else {
      if (filtered.length > 0) {
        displayGroups = [{
            label: `${filter.date}号收租 (共${filtered.length}户)`,
            rooms: sortRooms([...filtered])
        }];
      }
  }

  // Statistics Calculation
  const stats = filtered.reduce((acc, r) => {
      const d = calcDetails(r);
      acc.total += d.total;
      acc.rent += d.rent;
      acc.elec += d.elec;
      acc.water += d.water;
      if (r.status === 'paid') acc.collected += d.total;
      return acc;
  }, { total: 0, rent: 0, elec: 0, water: 0, collected: 0 });

  const toggleSelect = (id: string) => { 
    const newSet = new Set(batch.ids); 
    if (newSet.has(id)) newSet.delete(id); else newSet.add(id); 
    batch.setIds(newSet); 
  };

  const handleSelectAll = () => {
      const allFilteredIds = filtered.map(r => r.id);
      const isAllSelected = allFilteredIds.every(id => batch.ids.has(id));
      if (isAllSelected) {
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.delete(id));
          batch.setIds(newSet);
      } else {
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.add(id));
          batch.setIds(newSet);
      }
  };

  const openBatchBill = () => {
      setModal({ type: 'batchBill', data: Array.from(batch.ids) });
  };

  return (
    <div className="pb-24">
      <div className="sticky top-0 z-30 bg-[#F5F7FA]/95 backdrop-blur-sm border-b border-gray-200 shadow-sm">

        {/* Auth Status Banner - Compressed */}
        <div 
          onClick={() => setModal({ type: 'cloudAuth' })}
          className={`px-4 py-1 flex items-center justify-center gap-2 text-xs font-bold cursor-pointer transition-colors ${cloudUser ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-600 animate-pulse'}`}
        >
          {cloudUser ? (
            <><Check size={10}/> 已登录: {cloudUser.email}</>
          ) : (
            <><AlertCircle size={10}/> 未登录 (数据不保存) - 点击登录</>
          )}
        </div>

        <div className="px-4 py-2">
          {batch.isMode ? (
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 w-full bg-blue-50 p-2 rounded-lg border border-blue-200">
                    <button onClick={() => { batch.setMode(false); batch.setIds(new Set()); }} className="p-1 rounded hover:bg-blue-100">
                        <X className="text-blue-500" size={20}/>
                    </button>
                    <span className="font-bold text-blue-800 text-sm">已选 {batch.ids.size}</span>

                    <div className="ml-auto flex gap-2">
                        <button onClick={handleSelectAll} className="text-xs px-2 py-1.5 bg-white text-blue-600 rounded border border-blue-200 font-bold flex items-center gap-1">
                            <ListChecks size={14}/> 全选
                        </button>
                    </div>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={() => setModal({ type: 'batchEdit' })} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-gray-700 rounded border font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Settings2 size={14}/> 批量设置
                    </button>
                    <button 
                        onClick={openBatchBill} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-blue-600 rounded border border-blue-200 font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Copy size={14}/> 批量账单
                    </button>
                    <button 
                        onClick={() => confirmAction("批量删除?", `确定删除选中的 ${batch.ids.size} 个房间吗？`, actions.deleteBatch)} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-red-600 rounded border border-red-100 font-bold disabled:opacity-50"
                    >
                        删除
                    </button>
                </div>
            </div>
          ) : (
            <div className="flex items-center justify-between w-full">
              <div className="flex-shrink-0">
                <h1 className="text-xl font-black text-gray-800">房租管家</h1>
              </div>

              <div className="flex-1 flex justify-end pl-2">
                 <div className="flex items-center gap-2">
                    {installPrompt && (
                       <button onClick={onInstall} className="flex items-center justify-center gap-1 bg-black text-white px-2 py-1.5 rounded-full text-xs font-bold shadow-md hover:scale-105 transition-transform whitespace-nowrap">
                         <Download size={12}/> <span>安装</span>
                       </button>
                    )}
                    <button onClick={() => setModal({ type: 'cloudAuth' })} className="flex items-center justify-center gap-1 bg-white border border-blue-100 text-blue-600 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-blue-50 shadow-sm whitespace-nowrap">
                      <Cloud size={12}/> <span>云同步</span>
                    </button>
                    <button onClick={openGuide} className="flex items-center justify-center gap-1 bg-blue-100 text-blue-700 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-blue-200 whitespace-nowrap">
                      <BookOpen size={12}/> <span>指南</span>
                    </button>
                    <button onClick={() => setModal({ type: 'history' })} className="flex items-center justify-center gap-1 bg-gray-100 text-gray-700 px-2 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 whitespace-nowrap">
                      <History size={12}/> <span>历史</span>
                    </button>
                 </div>
              </div>
            </div>
          )}
        </div>

        {/* Compressed Filters */}
        <div className="bg-white/50 backdrop-blur-sm">
          <div className="px-4 py-1 flex gap-2 overflow-x-auto no-scrollbar">
            {allBuildings.map(b => (
              <button 
                key={b} 
                onClick={() => filter.setBuilding(b)} 
                className={`whitespace-nowrap px-3 py-1 rounded-lg text-xs font-bold transition-all border ${filter.building === b ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-500 border-gray-200'}`}
              >
                <Building2 size={12}/> {b === 'all' ? '所有房产' : b}
              </button>
            ))}
          </div>
          <div className="px-4 py-1 flex gap-2 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => filter.setDate('all')} 
              className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === 'all' ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
            >
              全部日期
            </button>
            {allPayDays.map(day => (
              <button 
                key={day} 
                onClick={() => filter.setDate(day.toString())} 
                className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === day.toString() ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
              >
                {day}号收租
              </button>
            ))}
          </div>
        </div>

        <div className="px-4 py-1.5 flex flex-col gap-1.5 bg-white border-t border-gray-100">
            <div className="flex gap-2">
              <div className="flex-1 flex items-center bg-gray-100 rounded-lg px-2 py-1">
                <Search className="text-gray-400" size={14} />
                <input 
                  className="bg-transparent text-xs p-1.5 outline-none w-full" 
                  placeholder="输入房号..." 
                  value={search.input} 
                  onChange={e => search.setInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && search.run()}
                />
                {search.input && <button onClick={search.clear}><X size={14} className="text-gray-400"/></button>}
              </div>
              <button onClick={search.run} className="bg-blue-600 text-white px-3 py-1 rounded-lg text-xs font-bold flex-shrink-0">搜索</button>
            </div>

            {!batch.isMode && (
                <div className="pt-1.5 border-t border-gray-50">
                    <div className="flex justify-between items-center mb-0.5">
                        <span className="text-xs text-gray-500">应收总计: <b className="text-gray-900 text-sm">¥{stats.total.toLocaleString()}</b></span>
                        <span className="text-xs text-green-600 font-bold">已收: ¥{stats.collected.toLocaleString()}</span>
                    </div>

                    <div className="flex justify-between items-center">
                         <div className="flex gap-2 text-[10px] text-gray-400">
                             <span>房租: ¥{stats.rent.toLocaleString()}</span>
                             <span className="w-px h-3 bg-gray-200"></span>
                             <span>水费: ¥{stats.water.toLocaleString()}</span>
                             <span className="w-px h-3 bg-gray-200"></span>
                             <span>电费: ¥{stats.elec.toLocaleString()}</span>
                         </div>
                         <div className="flex gap-2">
                            <button onClick={() => batch.setMode(true)} className="text-xs font-bold text-gray-600 bg-gray-100 px-2 py-1 rounded-lg flex items-center gap-1 active:bg-gray-200">
                                <CheckSquare size={10}/> 批量
                            </button>
                            <button onClick={() => setModal({ type: 'newMonth' })} className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg flex items-center gap-1 active:bg-blue-100">
                                <RotateCcw size={10}/> 结算
                            </button>
                         </div>
                    </div>
                </div>
            )}
        </div>
      </div>

      <div className="px-4 py-3 space-y-4">
        {displayGroups.map((group, index) => (
          <div key={index}>
            {group.label && (
              <div className="flex items-center gap-2 mb-2 pl-1">
                <span className="bg-gray-200 text-gray-600 text-[10px] font-bold px-2 py-0.5 rounded">{group.label}</span>
                <div className="h-px bg-gray-200 flex-1"></div>
              </div>
            )}
            <div className="grid grid-cols-1 gap-2.5">
              {group.rooms.map(room => {
                const details = calcDetails(room);
                const isPaid = room.status === 'paid';
                const isSelected = batch.ids.has(room.id);
                return (
                  <div 
                    key={room.id} 
                    onClick={() => batch.isMode ? toggleSelect(room.id) : navigate('edit', room.id)} 
                    className={`relative flex items-center gap-4 p-3 rounded-xl border transition-all bg-white ${batch.isMode && isSelected ? 'border-blue-500 bg-blue-50/20' : 'border-gray-100 shadow-[0_2px_5px_rgba(0,0,0,0.02)]'} ${!batch.isMode && isPaid ? 'opacity-60 grayscale' : 'hover:border-blue-200'}`}
                  >
                    {batch.isMode && (
                      <div className={`mr-1 ${isSelected ? 'text-blue-600' : 'text-gray-300'}`}>
                        {isSelected ? <CheckSquare size={20}/> : <Square size={20}/>}
                      </div>
                    )}
                    {!batch.isMode && <div className={`absolute left-0 top-3 bottom-3 w-1 rounded-r-full ${isPaid ? 'bg-green-400' : 'bg-red-500'}`}></div>}
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center mb-1">
                        <div className="flex items-baseline gap-2 overflow-hidden">
                          <span className="text-lg font-bold text-gray-800 whitespace-nowrap">{room.roomNo}</span>
                          {room.tenantName && (
                            <span className="text-xl font-bold text-gray-700 truncate ml-2">
                              {room.tenantName}
                            </span>
                          )}
                        </div>
                        <span className="text-lg font-bold font-mono text-gray-900 flex-shrink-0 ml-2">¥{details.total.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center h-5">
                        <span className="text-[10px] text-gray-400 flex items-center gap-1">
                          {/* Removed Building Info/Icon */}
                          {room.moveInDate && <span className="text-gray-400">入住: {room.moveInDate}</span>}
                        </span>
                        {!batch.isMode && !isPaid && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); setModal({ type: 'bill', data: room }); }} 
                            className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded hover:bg-blue-100"
                          >
                            账单
                          </button>
                        )}
                        {isPaid && <span className="text-[10px] font-bold text-green-600 flex items-center gap-1"><CheckCircle size={10}/> 已收</span>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {filtered.length === 0 && (
          <div className="text-center text-gray-400 py-20 flex flex-col items-center">
            <FileText size={48} className="mx-auto text-gray-200 mb-2"/>
            <p className="font-bold text-gray-500 mb-2">没有数据</p>
            {!cloudUser && <p className="text-xs text-red-400">请先登录云同步账号</p>}
          </div>
        )}
      </div>

      {!batch.isMode && (
        <button 
          onClick={() => navigate('add')} 
          className="fixed bottom-8 right-6 bg-blue-600 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center z-40 hover:scale-105 transition"
        >
          <Plus size={28} />
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Trash2, Zap, Droplets, LogOut, X, Calendar, User, Phone, History, CreditCard, Save } from 'lucide-react';
import { Room, AppConfig, ActionHandlers, ModalState } from '../types';

interface RoomEditViewProps {
  room: Room | undefined;
  config: AppConfig;
  actions: ActionHandlers;
  onBack: () => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
}

export const RoomEditView: React.FC<RoomEditViewProps> = ({ 
  room, 
  config, 
  actions, 
  onBack, 
  setModal, 
  confirmAction 
}) => {
  // --- Initialization with Deep Copy for Local State ---
  const [draft, setDraft] = useState<Room | null>(() => room ? JSON.parse(JSON.stringify(room)) : null);
  const [isDirty, setIsDirty] = useState(false);

  // Sync if room prop changes unexpectedly, but mainly rely on local draft
  useEffect(() => {
    if (room && (!draft || draft.id !== room.id)) {
        setDraft(JSON.parse(JSON.stringify(room)));
        setIsDirty(false);
    }
  }, [room]);

  if (!draft || !room) { 
    return null; 
  }

  const getVal = (v: any) => parseFloat(v) || 0;

  // Calculations based on DRAFT
  const elecPrice = draft.fixedElecPrice || '0';
  const waterPrice = draft.fixedWaterPrice || '0';

  const elecUsage = getVal(draft.elecCurr) - getVal(draft.elecPrev);
  const elecTotal = Math.max(0, elecUsage * getVal(elecPrice));
  const waterUsage = getVal(draft.waterCurr) - getVal(draft.waterPrev);
  const waterTotal = Math.max(0, waterUsage * getVal(waterPrice));
  const extraFees = draft.extraFees || [];
  const extraTotal = extraFees.reduce((sum, item) => sum + getVal(item.amount), 0);
  const grandTotal = getVal(draft.rent) + elecTotal + waterTotal + extraTotal;

  // Local State Update Handler
  const updateDraft = (f: keyof Room, v: any) => {
    setDraft(prev => prev ? ({ ...prev, [f]: v }) : null);
    setIsDirty(true);
  };

  // Special handler for Move-In Date change to sync PayDay
  const handleDateChange = (dateStr: string) => {
    setDraft(prev => {
        if (!prev) return null;
        const updates: Partial<Room> = { moveInDate: dateStr };
        if (dateStr) {
          const day = new Date(dateStr).getDate();
          if (!isNaN(day)) updates.payDay = day;
        }
        return { ...prev, ...updates };
    });
    setIsDirty(true);
  };

  const handleExtraChange = (newFees: any[]) => {
      updateDraft('extraFees', newFees);
  };

  const addExtra = () => handleExtraChange([...extraFees, { id: Date.now(), name: '', amount: '' }]);

  const updateExtra = (idx: number, f: string, v: string) => { 
    const n = [...extraFees]; 
    // @ts-ignore
    n[idx][f] = v; 
    handleExtraChange(n); 
  };

  const requestRemoveExtra = (idx: number) => {
    const newFees = extraFees.filter((_, i) => i !== idx);
    handleExtraChange(newFees);
  };

  const handleSave = () => {
      if (draft) {
          actions.saveRoom(draft.id, draft);
          setIsDirty(false);
      }
  };

  const handleBack = () => {
      if (isDirty) {
          confirmAction(
              "未保存修改", 
              "您修改了房间信息但尚未保存。确定要放弃修改并退出吗？", 
              onBack
          );
      } else {
          onBack();
      }
  };

  const toggleStatus = () => { 
    // Status toggle is an explicit action, usually instant. 
    // We can update draft OR execute action.
    // To prevent conflict with manual save, we'll just toggle in draft and require save, 
    // OR we execute immediately. Users prefer status toggle to be instant usually, 
    // but mixing manual save and instant action is confusing.
    // Let's make toggle status PART OF THE FORM (Manual Save).
    const newStatus = draft.status === 'paid' ? 'unpaid' : 'paid';
    updateDraft('status', newStatus);

    // HOWEVER, the button says "Confirm Payment". If I click it, I expect it to be done.
    // Let's save immediately for this specific action to be user friendly.
    actions.saveRoom(draft.id, { ...draft, status: newStatus });
    setDraft(prev => prev ? ({ ...prev, status: newStatus }) : null);
    setIsDirty(false); 
    // Optional: Auto-exit on payment? Maybe stay.
    if (newStatus === 'paid') onBack();
  };

  const handleMoveOutRequest = () => {
    setModal({ type: 'moveOut', data: draft }); // Pass draft data
  };

  const handleSingleSettle = () => {
      if (isDirty) {
          alert("请先保存当前修改后再进行结算");
          return;
      }
      confirmAction(
          "确认结算本月?", 
          "系统将保存当前账单到历史记录，把本月读数转为上月读数，并自动设置下一个账单周期的日期。", 
          () => actions.settleSingleRoom(room.id)
      );
  };

  // Validation Logic
  const isPhoneValid = !draft.tenantPhone || /^\d{11}$/.test(draft.tenantPhone);
  const isIdCardValid = !draft.tenantIdCard || /^.{18}$/.test(draft.tenantIdCard); 

  return (
    <div className="flex flex-col min-h-screen bg-white">
      <div className="px-4 py-3 flex items-center justify-between border-b border-gray-100 sticky top-0 bg-white z-20">
        <button onClick={handleBack} className="flex items-center gap-1 text-gray-600 hover:text-gray-900 font-bold text-sm">
          <ArrowLeft size={18}/> 返回
        </button>
        <span className="font-bold text-lg text-gray-800">{draft.roomNo}</span>

        <button 
          onClick={handleSave} 
          disabled={!isDirty}
          className={`flex items-center gap-1 px-3 py-1.5 rounded-lg transition-all ${isDirty ? 'bg-blue-600 text-white shadow-md' : 'bg-gray-100 text-gray-400'}`}
        >
          <Save size={16} />
          <span className="text-xs font-bold">保存</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 pb-32 space-y-8 mt-6">
        <div className="text-center bg-blue-50 py-6 rounded-2xl border border-blue-100 relative group">
          <p className="text-xs text-blue-400 font-bold uppercase mb-1">本月应收 (预览)</p>
          <div className="text-5xl font-black text-blue-900 font-mono tracking-tighter">¥{grandTotal.toLocaleString()}</div>
          <div className="absolute top-2 right-3 text-blue-300 text-xs font-bold bg-white/50 px-2 py-1 rounded-lg">押金: {draft.deposit || 0}</div>

          <button 
            onClick={() => setModal({ type: 'billHistory', data: room })} // History always uses saved state
            className="absolute top-2 left-3 text-blue-400 hover:text-blue-600 p-1 bg-white/50 rounded-lg flex items-center gap-1 text-xs font-bold"
          >
            <History size={14}/> 历史
          </button>
        </div>

        {/* Tenant Info */}
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
          <div className="flex items-center gap-2 mb-3">
             <User size={14} className="text-gray-500"/>
             <span className="text-xs font-bold text-gray-500">租客信息</span>
          </div>
          <div className="flex gap-4 mb-3">
             <div className="flex-1">
                 <div className="relative">
                    <User size={14} className="absolute left-2 top-2.5 text-gray-400" />
                    <input 
                      placeholder="租客姓名" 
                      className="w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border border-gray-200 rounded outline-none"
                      value={draft.tenantName || ''}
                      onChange={e => updateDraft('tenantName', e.target.value)}
                    />
                 </div>
             </div>
             <div className="flex-1">
                 <div className="relative">
                    <Phone size={14} className="absolute left-2 top-2.5 text-gray-400" />
                    <input 
                      type="tel"
                      placeholder="联系电话" 
                      className={`w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border rounded outline-none ${!isPhoneValid ? 'border-red-500 text-red-600 bg-red-50' : 'border-gray-200'}`}
                      value={draft.tenantPhone || ''}
                      onChange={e => updateDraft('tenantPhone', e.target.value)}
                    />
                 </div>
                 {!isPhoneValid && <p className="text-[10px] text-red-500 mt-1 pl-1">电话需11位</p>}
             </div>
          </div>

          <div className="w-full">
             <div className="relative">
                <CreditCard size={14} className="absolute left-2 top-2.5 text-gray-400" />
                <input 
                  placeholder="身份证号" 
                  className={`w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border rounded outline-none ${!isIdCardValid ? 'border-red-500 text-red-600 bg-red-50' : 'border-gray-200'}`}
                  value={draft.tenantIdCard || ''}
                  onChange={e => updateDraft('tenantIdCard', e.target.value)}
                  maxLength={18}
                />
             </div>
             {!isIdCardValid && <p className="text-[10px] text-red-500 mt-1 pl-1">身份证需18位</p>}
          </div>
        </div>

        {/* Room Details Grid */}
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">房租(元)</label>
            <input type="number" value={draft.rent || ''} onChange={(e) => updateDraft('rent', e.target.value)} className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none" placeholder="" />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">押金(元)</label>
            <input type="number" value={draft.deposit || ''} onChange={(e) => updateDraft('deposit', e.target.value)} className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none text-blue-600" placeholder="" />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">入住日期</label>
            <input 
              type="date" 
              value={draft.moveInDate || ''} 
              onChange={(e) => handleDateChange(e.target.value)} 
              className="w-full text-sm font-bold border-b border-gray-200 py-1.5 outline-none" 
            />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">收租时间(号)</label>
            <input 
              type="number" 
              value={draft.payDay || ''} 
              onChange={(e) => updateDraft('payDay', parseInt(e.target.value))} 
              className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none" 
              placeholder="" 
            />
          </div>
        </div>

        {/* Billing Cycle Section */}
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
           <div className="flex items-center justify-between mb-2">
             <div className="flex items-center gap-2">
               <Calendar size={14} className="text-gray-500"/>
               <span className="text-xs font-bold text-gray-500">账单日期 (选填)</span>
             </div>
             <button
               onClick={handleSingleSettle}
               className="text-[10px] bg-blue-600 text-white px-2 py-1 rounded font-bold shadow-sm hover:bg-blue-700"
             >
               📅 结算/开启下月
             </button>
           </div>
           <div className="flex items-center gap-2">
             <input 
               type="date" 
               className="flex-1 bg-white border border-gray-200 rounded px-2 py-2 text-sm font-bold text-gray-800 outline-none"
               value={draft.billStartDate || ''}
               onChange={e => updateDraft('billStartDate', e.target.value)}
             />
             <span className="text-gray-400 text-xs">至</span>
             <input 
               type="date" 
               className="flex-1 bg-white border border-gray-200 rounded px-2 py-2 text-sm font-bold text-gray-800 outline-none"
               value={draft.billEndDate || ''}
               onChange={e => updateDraft('billEndDate', e.target.value)}
             />
           </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white border border-gray-100 p-4 rounded-xl shadow-sm relative">
            <div className="flex justify-between mb-3 items-center">
              <div className="flex items-center gap-2">
                  <div className="text-sm font-bold text-gray-800 flex items-center gap-2">
                    <Zap size={16} className="text-yellow-500"/> 电费
                  </div>
                  {/* Added Usage Display */}
                  {elecUsage > 0 && (
                      <span className="text-[10px] text-gray-400 font-bold bg-gray-100 px-1.5 py-0.5 rounded">
                        用量: {elecUsage.toFixed(1)}度
                      </span>
                  )}
              </div>

              <div className="flex items-center gap-2">
                  {/* Requirement 2: Editable Unit Price, no placeholder */}
                  <div className="flex items-center gap-1 bg-yellow-50 px-2 py-1 rounded">
                    <span className="text-[10px] font-bold text-yellow-700">单价:</span>
                    <input 
                        type="number" 
                        value={draft.fixedElecPrice || ''} 
                        onChange={e => updateDraft('fixedElecPrice', e.target.value)}
                        className="w-12 bg-transparent text-xs font-bold text-yellow-700 outline-none border-b border-yellow-200 text-right"
                    />
                  </div>
                  <span className="font-bold text-yellow-600">¥{elecTotal.toFixed(1)}</span>
              </div>
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 block mb-1">上月读数</label>
                <input type="number" value={draft.elecPrev || ''} onChange={(e) => updateDraft('elecPrev', e.target.value)} className="w-full bg-gray-50 rounded p-2 text-sm font-bold text-gray-500 outline-none" placeholder=""/>
              </div>
              <div className="flex-1">
                <label className="text-[10px] text-blue-600 font-bold block mb-1">本月读数</label>
                <input type="number" autoFocus value={draft.elecCurr || ''} onChange={(e) => updateDraft('elecCurr', e.target.value)} className="w-full bg-blue-50 border border-blue-200 rounded p-2 text-lg font-bold text-gray-900 outline-none" placeholder=""/>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-4 rounded-xl shadow-sm">
            <div className="flex justify-between mb-3 items-center">
              <div className="flex items-center gap-2">
                  <div className="text-sm font-bold text-gray-800 flex items-center gap-2">
                    <Droplets size={16} className="text-blue-500"/> 水费
                  </div>
                  {/* Added Usage Display */}
                  {waterUsage > 0 && (
                      <span className="text-[10px] text-gray-400 font-bold bg-gray-100 px-1.5 py-0.5 rounded">
                        用量: {waterUsage.toFixed(1)}吨
                      </span>
                  )}
              </div>

               <div className="flex items-center gap-2">
                   {/* Requirement 2: Editable Unit Price, no placeholder */}
                   <div className="flex items-center gap-1 bg-blue-50 px-2 py-1 rounded">
                    <span className="text-[10px] font-bold text-blue-700">单价:</span>
                    <input 
                        type="number" 
                        value={draft.fixedWaterPrice || ''} 
                        onChange={e => updateDraft('fixedWaterPrice', e.target.value)}
                        className="w-12 bg-transparent text-xs font-bold text-blue-700 outline-none border-b border-blue-200 text-right"
                    />
                  </div>
                  <span className="font-bold text-blue-600">¥{waterTotal.toFixed(1)}</span>
              </div>
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 block mb-1">上月读数</label>
                <input type="number" value={draft.waterPrev || ''} onChange={(e) => updateDraft('waterPrev', e.target.value)} className="w-full bg-gray-50 rounded p-2 text-sm font-bold text-gray-500 outline-none" placeholder=""/>
              </div>
              <div className="flex-1">
                <label className="text-[10px] text-blue-600 font-bold block mb-1">本月读数</label>
                <input type="number" value={draft.waterCurr || ''} onChange={(e) => updateDraft('waterCurr', e.target.value)} className="w-full bg-blue-50 border border-blue-200 rounded p-2 text-lg font-bold text-gray-900 outline-none" placeholder=""/>
              </div>
            </div>
          </div>
        </div>

        <div>
          <div className="flex justify-between items-center mb-2">
            <label className="text-xs font-bold text-gray-400 uppercase">额外费用</label>
            <button onClick={addExtra} className="text-blue-600 text-xs font-bold bg-blue-50 px-2 py-1 rounded">+ 添加</button>
          </div>
          <div className="space-y-3">
            {extraFees.map((fee, idx) => (
              <div key={idx} className="flex items-center gap-3">
                <input placeholder="项目" value={fee.name} onChange={(e) => updateExtra(idx, 'name', e.target.value)} className="flex-1 border-b border-gray-100 py-2 text-sm font-bold outline-none"/>
                <input type="number" placeholder="0" value={fee.amount} onChange={(e) => updateExtra(idx, 'amount', e.target.value)} className="w-20 border-b border-gray-100 py-2 text-sm font-bold text-right outline-none"/>
                <button onClick={() => requestRemoveExtra(idx)} className="text-gray-300 hover:text-red-500">
                  <X size={16}/>
                </button>
              </div>
            ))}
          </div>
        </div>

        <div className="pt-4 border-t border-gray-100 flex flex-col gap-3">
          <button onClick={handleMoveOutRequest} className="w-full py-3 border border-red-200 text-red-600 rounded-xl font-bold text-sm flex items-center justify-center gap-2">
            <LogOut size={16}/> 办理退租
          </button>

          <button 
            onClick={() => confirmAction("删除房间?", "确定删除此房间吗？数据可恢复。", () => actions.deleteSingle(room.id))} 
            className="w-full py-3 border border-gray-100 text-gray-400 rounded-xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-gray-50 hover:text-red-400"
          >
            <Trash2 size={16} /> 删除房间
          </button>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-5 bg-white border-t border-gray-100 z-40">
        <div className="grid grid-cols-[1fr_2fr] gap-4 max-w-md mx-auto">
          <button onClick={() => setModal({ type: 'bill', data: isDirty ? draft : room })} className="bg-gray-100 text-gray-600 rounded-lg py-3 font-bold text-sm">
             {isDirty ? '预览账单(未保存)' : '生成账单'}
          </button>
          <button onClick={toggleStatus} className={`rounded-lg py-3 font-bold text-white shadow-sm flex items-center justify-center gap-2 ${draft.status === 'paid' ? 'bg-gray-400' : 'bg-black'}`}>
            {draft.status === 'paid' ? '标记未收' : '确认收款'}
          </button>
        </div>
      </div>
    </div>
  );
};
